#!/usr/bin/env node
/**
 * Generates the Google Play feature graphic into docs/:
 *   play-feature-graphic.png   1024×500
 *
 * The 512×512 Play icon is now generated by generate-icon.js.
 *
 * Run: node scripts/generate-store-assets.js
 */
const path = require('path');
const sharp = require('sharp');

const CREAM    = '#FDF6E9';
const GOLD     = '#C9973B';
const GOLD_DEEP = '#A47A2A';
const TEXT     = '#3D3225';
const MUTED    = '#85765F';

const SRC    = path.join(__dirname, '..', 'assets', 'images', 'android-icon-foreground.png');
const outDir = path.join(__dirname, '..', 'docs');

async function main() {
  // Background + right-side wordmark as SVG
  const bgSvg = `<svg xmlns="http://www.w3.org/2000/svg" width="1024" height="500">
    <rect width="1024" height="500" fill="${CREAM}"/>
    <rect x="498" y="50" width="2" height="400" rx="1" fill="${GOLD_DEEP}" opacity="0.25"/>
    <text x="762" y="200" font-family="Georgia, 'Times New Roman', serif"
          font-size="66" fill="${TEXT}" text-anchor="middle" font-weight="bold">Family &amp;</text>
    <text x="762" y="278" font-family="Georgia, 'Times New Roman', serif"
          font-size="66" fill="${TEXT}" text-anchor="middle" font-weight="bold">Faith</text>
    <text x="762" y="336" font-family="Georgia, 'Times New Roman', serif"
          font-size="26" fill="${MUTED}" text-anchor="middle">The Bible in a year — together.</text>
    <rect x="622" y="362" width="280" height="5" rx="2.5" fill="${GOLD}"/>
  </svg>`;

  const bgBuf = await sharp(Buffer.from(bgSvg)).png().toBuffer();

  // Scale icon artwork to fill the left half (440×440, centered in 498×500 area)
  const iconBuf = await sharp(SRC)
    .resize(440, 440, { fit: 'contain', background: { r: 0, g: 0, b: 0, alpha: 0 } })
    .png()
    .toBuffer();

  await sharp(bgBuf)
    .composite([{ input: iconBuf, left: 29, top: 30 }])
    .png()
    .toFile(path.join(outDir, 'play-feature-graphic.png'));

  console.log('✔ docs/play-feature-graphic.png (1024×500)');
}

main().catch((err) => { console.error(err); process.exit(1); });
